1	/**
2	 * @file Live four-agent reasoning and peer-review integration test.
3	 * @change 2026-11-07 FR-FRENEMY-117, TR-FRENEMY-ORCH-121,
4	 * TEST-FRENEMY-117, AC-FRENEMY-117-01 through AC-FRENEMY-117-05,
5	 * AC-TR-FRENEMY-ORCH-121-01 through AC-TR-FRENEMY-ORCH-121-06, and
6	 * AC-TEST-FRENEMY-117-Q01 through Q05 and AC-TEST-FRENEMY-117-06 through 08:
7	 * Bound the green mock contract to the existing Frenemy read-only tools and
8	 * Codex CLI while retaining complete boundary-visible session evidence.
9	 * @change 2026-11-07 TEST-FRENEMY-117 and AC-TEST-FRENEMY-117-08: Reject a
10	 * substituted Claude executable before live orchestration so the retained
11	 * executable version is bound to the command the relay can resolve.
12	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 and 07: Bind
13	 * sequential advancement to the shared complete per-question evidence gate and
14	 * retain the actual process result in every transcript.
15	 * @change 2026-11-07 TEST-FRENEMY-117, AC-TEST-FRENEMY-117-06 through 08:
16	 * Retain every settled parallel session and its orchestration request/result,
17	 * including failures, before rejecting the active question.
18	 * @change 2026-11-07 TEST-FRENEMY-117 and AC-FRENEMY-117-04: Retain every
19	 * settled review session when one review result cannot be parsed, record the
20	 * parse failure, and reject only after the complete settled batch is retained.
21	 * @change 2026-11-07 TEST-FRENEMY-117 and AC-FRENEMY-117-04: Retain a
22	 * synthesized failed session, transcript, and stderr record when a rejected
23	 * participant promise has no session metadata. The test-only
24	 * FRENEMY_FOUR_AGENT_FORCE_SESSION_METADATA_FAILURE_AGENT seam proves this
25	 * path and is never set by a Nuke target.
26	 * @change 2026-11-07 TEST-FRENEMY-117 and AC-FRENEMY-117-04: The test-only
27	 * FRENEMY_FOUR_AGENT_FORCE_REVIEW_PARSE_FAILURE_AGENT seam replaces one named
28	 * reviewer's successful response with invalid JSON before parsing. It is never
29	 * set by a Nuke target.
30	 */
31	import assert from "node:assert/strict";
32	import { spawn } from "node:child_process";
33	import { existsSync, readFileSync } from "node:fs";
34	import { mkdir, readdir, readFile, stat, writeFile } from "node:fs/promises";
35	import { homedir } from "node:os";
36	import { basename, delimiter, dirname, isAbsolute, join, relative } from "node:path";
37	import { setTimeout as delay } from "node:timers/promises";
38	import { fileURLToPath } from "node:url";
39	import test from "node:test";
40	import {
41	  PARTICIPANTS,
42	  answerPrompt,
43	  assertFourAgentCoreEvidence,
44	  loadQuestionFixture,
45	  reviewPrompt,
46	  runQuestionSequence,
47	} from "../contracts/four-agent-reasoning.mjs";
48	
49	const here = dirname(fileURLToPath(import.meta.url));
50	const repo = dirname(dirname(here));
51	const relayPath = join(repo, "ask-claude-mcp.mjs");
52	const fixturePath = join(here, "..", "fixtures", "four-agent-reasoning-questions.json");
53	const fixture = loadQuestionFixture(fixturePath);
54	const runId = process.env.FRENEMY_FOUR_AGENT_RUN_ID;
55	const artifactRoot = process.env.FRENEMY_FOUR_AGENT_RESULT_ROOT;
56	const executables = Object.freeze({
57	  claude: process.env.FRENEMY_CLAUDE_EXECUTABLE,
58	  codex: process.env.FRENEMY_CODEX_EXECUTABLE,
59	  grok: process.env.FRENEMY_GROK_EXECUTABLE,
60	  cline: process.env.FRENEMY_CLINE_EXECUTABLE,
61	});
62	const sessionTimeoutMilliseconds = Number.parseInt(process.env.FRENEMY_FOUR_AGENT_SESSION_TIMEOUT_MS ?? "1800000", 10);
63	const forcedReviewParseFailureAgent = process.env.FRENEMY_FOUR_AGENT_FORCE_REVIEW_PARSE_FAILURE_AGENT;
64	const forcedSessionMetadataFailureAgent = process.env.FRENEMY_FOUR_AGENT_FORCE_SESSION_METADATA_FAILURE_AGENT;
65	
66	function localTimestamp(date = new Date()) {
67	  const pad = (value) => String(value).padStart(2, "0");
68	  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
69	}
70	
71	function relativePath(path) {
72	  return relative(artifactRoot, path).replaceAll("\\", "/");
73	}
74	
75	async function writeJson(path, value) {
76	  await mkdir(dirname(path), { recursive: true });
77	  await writeFile(path, `${JSON.stringify(value, null, 2)}\n`, "utf8");
78	}
79	
80	async function writeJsonl(path, values) {
81	  await mkdir(dirname(path), { recursive: true });
82	  await writeFile(path, values.map((value) => `${JSON.stringify(value)}\n`).join(""), "utf8");
83	}
84	
85	function event({ questionId, phase, agent, sessionId, timestamp = localTimestamp(), direction, eventType, payload }) {
86	  return { runId, questionId, phase, agent, sessionId, timestamp, direction, eventType, payload };
87	}
88	
89	async function requireExecutable(agent, path) {
90	  assert.ok(path, `${agent} executable was not provided`);
91	  assert.ok(isAbsolute(path), `${agent} executable must be absolute`);
92	  assert.ok(existsSync(path), `${agent} executable does not exist: ${path}`);
93	  assert.ok((await stat(path)).isFile(), `${agent} executable is not a file: ${path}`);
94	  if (agent === "claude") {
95	    const expectedName = process.platform === "win32" ? "claude.exe" : "claude";
96	    assert.equal(
97	      basename(path).toLowerCase(),
98	      expectedName,
99	      `claude executable must be named ${expectedName} so the relay resolves the configured command`,
100	    );
101	  }
102	}
103	
104	async function clineSessionDirectories() {
105	  const root = join(homedir(), ".cline", "data", "sessions");
106	  try {
107	    return new Set((await readdir(root, { withFileTypes: true })).filter((entry) => entry.isDirectory()).map((entry) => entry.name));
108	  } catch {
109	    return new Set();
110	  }
111	}
112	
113	async function readNewClineSessionIdentities(before) {
114	  const root = join(homedir(), ".cline", "data", "sessions");
115	  for (let attempt = 0; attempt < 40; attempt += 1) {
116	    const after = await clineSessionDirectories();
117	    const identities = [];
118	    for (const name of after) {
119	      if (before.has(name)) continue;
120	      const files = await readdir(join(root, name));
121	      const metadata = files.find((file) => file.endsWith(".json") && !file.endsWith(".messages.json"));
122	      if (!metadata) continue;
123	      const parsed = JSON.parse(await readFile(join(root, name, metadata), "utf8"));
124	      identities.push({ sessionId: parsed.session_id, provider: parsed.provider, model: parsed.model });
125	    }
126	    if (identities.length > 0) return identities;
127	    await delay(250);
128	  }
129	  return [];
130	}
131	
132	function extractRelayText(message) {
133	  assert.ok(message?.result, "relay response omitted result");
134	  assert.equal(message.result.isError, false, message.result.content?.[0]?.text ?? "relay reported an error");
135	  assert.equal(message.result.content?.length, 1, "relay response must contain one text item");
136	  assert.equal(message.result.content[0].type, "text", "relay response must contain text");
137	  const text = message.result.content[0].text;
138	  assert.ok(text.trim(), "relay returned an empty answer");
139	  return text;
140	}
141	
142	async function runRelaySession(agent, role, question, prompt) {
143	  const startedAt = localTimestamp();
144	  const beforeClineSessions = agent === "cline" ? await clineSessionDirectories() : null;
145	  const sessionId = `${runId}-${question.id}-${agent}-${role}`;
146	  const transcriptPath = join(artifactRoot, "sessions", agent, question.id, `${role}.jsonl`);
147	  const stderrPath = join(artifactRoot, "stderr", agent, question.id, `${role}.log`);
148	  const transcript = [];
149	  const stderr = [];
150	  const args = [relayPath, "--grok-executable", executables.grok, "--cline-executable", executables.cline];
151	  const tool = { claude: "ask_claude", grok: "ask_grok", cline: "ask_cline" }[agent];
152	  const toolArguments = { prompt, effort: "medium" };
153	  if (agent === "cline") Object.assign(toolArguments, { provider: "openai-codex", model: "gpt-5.6-luna" });
154	  const child = spawn(process.execPath, args, {
155	    cwd: repo,
156	    shell: false,
157	    stdio: ["pipe", "pipe", "pipe"],
158	    env: { ...process.env, PATH: `${dirname(executables.claude)}${delimiter}${process.env.PATH ?? ""}` },
159	  });
160	  child.stdout.setEncoding("utf8");
161	  child.stderr.setEncoding("utf8");
162	  let buffer = "";
163	  let nextId = 1;
164	  const pending = new Map();
165	  let closeResult;
166	  const closed = new Promise((resolve) => {
167	    child.once("close", (code, signal) => {
168	      closeResult = { code, signal };
169	      for (const waiter of pending.values()) waiter.reject(new Error(`relay exited before response: ${code}/${signal}`));
170	      pending.clear();
171	      resolve(closeResult);
172	    });
173	  });
174	  child.stderr.on("data", (chunk) => stderr.push(chunk));
175	  child.stdout.on("data", (chunk) => {
176	    buffer += chunk;
177	    let newline;
178	    while ((newline = buffer.indexOf("\n")) >= 0) {
179	      const line = buffer.slice(0, newline).trim();
180	      buffer = buffer.slice(newline + 1);
181	      if (!line) continue;
182	      const message = JSON.parse(line);
183	      transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "response", eventType: "relay_jsonrpc", payload: message }));
184	      const waiter = pending.get(message.id);
185	      if (waiter) {
186	        clearTimeout(waiter.timer);
187	        pending.delete(message.id);
188	        waiter.resolve(message);
189	      }
190	    }
191	  });
192	
193	  const request = (method, params = {}) => {
194	    const id = nextId++;
195	    const message = { jsonrpc: "2.0", id, method, params };
196	    transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "request", eventType: "relay_jsonrpc", payload: message }));
197	    child.stdin.write(`${JSON.stringify(message)}\n`);
198	    return new Promise((resolve, reject) => {
199	      const timer = setTimeout(() => {
200	        pending.delete(id);
201	        child.kill("SIGKILL");
202	        reject(new Error(`${agent} ${role} session timed out`));
203	      }, sessionTimeoutMilliseconds);
204	      pending.set(id, { resolve, reject, timer });
205	    });
206	  };
207	
208	  let status = "failed";
209	  try {
210	    const initialized = await request("initialize", { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "frenemy-four-agent-test", version: "1.0.0" } });
211	    assert.equal(initialized.result.serverInfo.name, "frenemy", "wrong relay identity");
212	    const notification = { jsonrpc: "2.0", method: "notifications/initialized", params: {} };
213	    transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "request", eventType: "relay_jsonrpc", payload: notification }));
214	    child.stdin.write(`${JSON.stringify(notification)}\n`);
215	    const response = await request("tools/call", { name: tool, arguments: toolArguments });
216	    const text = extractRelayText(response);
217	    transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "response", eventType: "agent_result", payload: { text } }));
218	    status = "completed";
219	    child.stdin.end();
220	    const exit = await closed;
221	    assert.equal(exit.code, 0, `${agent} relay exited with code ${exit.code}`);
222	    const completedAt = localTimestamp();
223	    let observedIdentities;
224	    let identityPath;
225	    if (agent === "cline") {
226	      observedIdentities = await readNewClineSessionIdentities(beforeClineSessions);
227	      assert.ok(observedIdentities.length > 0, "Cline created no observable session identity record");
228	      for (const identity of observedIdentities) {
229	        assert.equal(identity.provider, "openai-codex", "Cline used a substituted provider");
230	        assert.equal(identity.model, "gpt-5.6-luna", "Cline used a substituted model");
231	      }
232	      const absoluteIdentityPath = join(artifactRoot, "session-identities", agent, question.id, `${role}.json`);
233	      await writeJson(absoluteIdentityPath, { selected: { provider: "openai-codex", model: "gpt-5.6-luna", effort: "medium" }, observed: observedIdentities });
234	      identityPath = relativePath(absoluteIdentityPath);
235	    }
236	    return {
237	      text,
238	      session: {
239	        questionId: question.id,
240	        agent,
241	        role,
242	        sessionId,
243	        effort: "medium",
244	        status,
245	        startedAt,
246	        completedAt,
247	        transcriptPath: relativePath(transcriptPath),
248	        transcriptComplete: exit.code === 0
249	          && transcript.some((item) => item.direction === "request" && item.payload?.method === "tools/call")
250	          && transcript.some((item) => item.direction === "response" && item.payload?.id === response.id),
251	        resultText: text,
252	        stderrPath: relativePath(stderrPath),
253	        target: executables[agent],
254	        relayArgv: args,
255	        requestedConfiguration: { effort: "medium", ...(agent === "cline" ? { provider: "openai-codex", model: "gpt-5.6-luna" } : {}) },
256	        ...(observedIdentities ? { observedIdentities } : {}),
257	        ...(identityPath ? { identityPath } : {}),
258	      },
259	    };
260	  } catch (error) {
261	    transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "internal", eventType: "session_failure", payload: { message: error.message } }));
262	    error.session = {
263	      questionId: question.id,
264	      agent,
265	      role,
266	      sessionId,
267	      effort: "medium",
268	      status: "failed",
269	      startedAt,
270	      completedAt: localTimestamp(),
271	      transcriptPath: relativePath(transcriptPath),
272	      transcriptComplete: false,
273	      resultText: "",
274	      stderrPath: relativePath(stderrPath),
275	      target: executables[agent],
276	      relayArgv: args,
277	      requestedConfiguration: { effort: "medium", ...(agent === "cline" ? { provider: "openai-codex", model: "gpt-5.6-luna" } : {}) },
278	    };
279	    throw error;
280	  } finally {
281	    if (child.exitCode === null && !child.killed) child.kill("SIGKILL");
282	    transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "internal", eventType: "session_exit", payload: closeResult ?? { code: child.exitCode, signal: child.signalCode, status } }));
283	    if (stderr.length > 0) transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "response", eventType: "stderr", payload: { text: stderr.join("") } }));
284	    await writeJsonl(transcriptPath, transcript);
285	    await mkdir(dirname(stderrPath), { recursive: true });
286	    await writeFile(stderrPath, stderr.join(""), "utf8");
287	  }
288	}
289	
290	async function runCodexSession(role, question, prompt) {
291	  const startedAt = localTimestamp();
292	  const agent = "codex";
293	  const sessionId = `${runId}-${question.id}-${agent}-${role}`;
294	  const transcriptPath = join(artifactRoot, "sessions", agent, question.id, `${role}.jsonl`);
295	  const stderrPath = join(artifactRoot, "stderr", agent, question.id, `${role}.log`);
296	  const lastMessagePath = join(artifactRoot, "last-messages", agent, question.id, `${role}.txt`);
297	  await mkdir(dirname(lastMessagePath), { recursive: true });
298	  const args = ["exec", "--sandbox", "read-only", "--json", "-c", "model_reasoning_effort=medium", "-C", repo, "-o", lastMessagePath, "-"];
299	  const transcript = [event({ questionId: question.id, phase: role, agent, sessionId, timestamp: startedAt, direction: "request", eventType: "codex_prompt", payload: { prompt, executable: executables.codex, argv: args } })];
300	  const child = spawn(executables.codex, args, { cwd: repo, shell: false, stdio: ["pipe", "pipe", "pipe"] });
301	  child.stdout.setEncoding("utf8");
302	  child.stderr.setEncoding("utf8");
303	  let stdout = "";
304	  let stderr = "";
305	  child.stdout.on("data", (chunk) => { stdout += chunk; });
306	  child.stderr.on("data", (chunk) => { stderr += chunk; });
307	  const closed = new Promise((resolve) => child.once("close", (code, signal) => resolve({ code, signal })));
308	  const timer = setTimeout(() => child.kill("SIGKILL"), sessionTimeoutMilliseconds);
309	  child.stdin.end(prompt);
310	  let status = "failed";
311	  try {
312	    const exit = await closed;
313	    clearTimeout(timer);
314	    for (const line of stdout.split(/\r?\n/u).filter(Boolean)) {
315	      transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "response", eventType: "codex_jsonl", payload: JSON.parse(line) }));
316	    }
317	    transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "internal", eventType: "session_exit", payload: exit }));
318	    if (stderr) transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "response", eventType: "stderr", payload: { text: stderr } }));
319	    assert.equal(exit.code, 0, `codex ${role} session exited with code ${exit.code}`);
320	    const text = readFileSync(lastMessagePath, "utf8");
321	    assert.ok(text.trim(), "codex returned an empty answer");
322	    transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "response", eventType: "agent_result", payload: { text } }));
323	    status = "completed";
324	    return { text, session: { questionId: question.id, agent, role, sessionId, effort: "medium", status, startedAt, completedAt: localTimestamp(), transcriptPath: relativePath(transcriptPath), transcriptComplete: exit.code === 0 && transcript.some((item) => item.eventType === "codex_prompt") && transcript.some((item) => item.eventType === "agent_result"), resultText: text, stderrPath: relativePath(stderrPath), target: executables.codex, argv: args, requestedConfiguration: { effort: "medium" } } };
325	  } catch (error) {
326	    transcript.push(event({ questionId: question.id, phase: role, agent, sessionId, direction: "internal", eventType: "session_failure", payload: { message: error.message } }));
327	    error.session = {
328	      questionId: question.id,
329	      agent,
330	      role,
331	      sessionId,
332	      effort: "medium",
333	      status: "failed",
334	      startedAt,
335	      completedAt: localTimestamp(),
336	      transcriptPath: relativePath(transcriptPath),
337	      transcriptComplete: false,
338	      resultText: "",
339	      stderrPath: relativePath(stderrPath),
340	      target: executables.codex,
341	      argv: args,
342	      requestedConfiguration: { effort: "medium" },
343	    };
344	    throw error;
345	  } finally {
346	    clearTimeout(timer);
347	    await writeJsonl(transcriptPath, transcript);
348	    await mkdir(dirname(stderrPath), { recursive: true });
349	    await writeFile(stderrPath, stderr, "utf8");
350	  }
351	}
352	
353	function runParticipantSession(agent, role, question, prompt) {
354	  if (agent === forcedSessionMetadataFailureAgent) {
355	    return Promise.reject(new Error(`forced ${agent} ${role} failure without session metadata`));
356	  }
357	  return agent === "codex" ? runCodexSession(role, question, prompt) : runRelaySession(agent, role, question, prompt);
358	}
359	
360	function appendOrchestrationRequests(orchestration, role, question, prompts) {
361	  for (const agent of PARTICIPANTS) {
362	    orchestration.push(event({
363	      questionId: question.id,
364	      phase: role,
365	      agent,
366	      sessionId: `${runId}-${question.id}-${agent}-${role}`,
367	      direction: "request",
368	      eventType: `${role}_prompt`,
369	      payload: {
370	        prompt: prompts.get(agent),
371	        requestedConfiguration: { effort: "medium", ...(agent === "cline" ? { provider: "openai-codex", model: "gpt-5.6-luna" } : {}) },
372	      },
373	    }));
374	  }
375	}
376	
377	async function retainSettledSession({ result, role, question, agent, sessions, orchestration }) {
378	  if (result.status === "fulfilled") {
379	    sessions.push(result.value.session);
380	    return result.value;
381	  }
382	  let session = result.reason?.session;
383	  if (!session) {
384	    const startedAt = localTimestamp();
385	    const completedAt = localTimestamp();
386	    const sessionId = `${runId}-${question.id}-${agent}-${role}`;
387	    const transcriptPath = `sessions/${agent}/${question.id}/${role}.jsonl`;
388	    const stderrPath = `stderr/${agent}/${question.id}/${role}.log`;
389	    const message = result.reason?.message ?? String(result.reason);
390	    session = {
391	      questionId: question.id,
392	      agent,
393	      role,
394	      sessionId,
395	      effort: "medium",
396	      status: "failed",
397	      startedAt,
398	      completedAt,
399	      transcriptPath,
400	      transcriptComplete: false,
401	      resultText: "",
402	      stderrPath,
403	      target: executables[agent],
404	      requestedConfiguration: { effort: "medium", ...(agent === "cline" ? { provider: "openai-codex", model: "gpt-5.6-luna" } : {}) },
405	      synthesizedFailureEvidence: true,
406	    };
407	    await writeJsonl(join(artifactRoot, transcriptPath), [
408	      event({ questionId: question.id, phase: role, agent, sessionId, timestamp: startedAt, direction: "internal", eventType: "session_failure", payload: { message, synthesized: true } }),
409	      event({ questionId: question.id, phase: role, agent, sessionId, timestamp: completedAt, direction: "internal", eventType: "session_exit", payload: { code: null, signal: null, status: "failed", synthesized: true } }),
410	    ]);
411	    await mkdir(dirname(join(artifactRoot, stderrPath)), { recursive: true });
412	    await writeFile(join(artifactRoot, stderrPath), `${message}\n`, "utf8");
413	  }
414	  sessions.push(session);
415	  orchestration.push(event({
416	    questionId: question.id,
417	    phase: role,
418	    agent,
419	    sessionId: session.sessionId,
420	    timestamp: session.completedAt,
421	    direction: "response",
422	    eventType: `${role}_failure`,
423	    payload: { name: result.reason?.name ?? "Error", message: result.reason?.message ?? String(result.reason), status: "failed" },
424	  }));
425	  return null;
426	}
427	
428	async function collectFiles(root) {
429	  const files = {};
430	  const visit = async (directory) => {
431	    for (const entry of await readdir(directory, { withFileTypes: true })) {
432	      const path = join(directory, entry.name);
433	      if (entry.isDirectory()) await visit(path);
434	      else if (entry.name !== "manifest.json") files[relative(root, path).replaceAll("\\", "/")] = await readFile(path, "utf8");
435	    }
436	  };
437	  await visit(root);
438	  return files;
439	}
440	
441	async function buildLiveCoreEvidence({ answers, judgments, sessions, orchestration }) {
442	  const files = await collectFiles(artifactRoot);
443	  return { runId, fixture, participants: [...PARTICIPANTS], answers, judgments, sessions, orchestration, files };
444	}
445	
446	function parseJudgments(text, reviewerAgent, question) {
447	  const judgments = JSON.parse(text.trim());
448	  assert.ok(Array.isArray(judgments), `${reviewerAgent} review must be a JSON array`);
449	  assert.equal(judgments.length, 3, `${reviewerAgent} review must contain exactly three judgments`);
450	  return judgments.map((judgment) => ({ ...judgment, questionId: judgment.questionId, reviewerAgent: judgment.reviewerAgent }));
451	}
452	
453	test("FourAgentReasoningIntegrationTests all four agents answer and peer-review the five AC questions", async () => {
454	  assert.ok(runId, "FRENEMY_FOUR_AGENT_RUN_ID is required");
455	  assert.ok(artifactRoot && isAbsolute(artifactRoot), "FRENEMY_FOUR_AGENT_RESULT_ROOT must be absolute");
456	  assert.ok(Number.isInteger(sessionTimeoutMilliseconds) && sessionTimeoutMilliseconds > 0, "session timeout must be a positive integer");
457	  await mkdir(artifactRoot, { recursive: true });
458	  await writeJson(join(artifactRoot, "questions.json"), fixture);
459	
460	  const answers = [];
461	  const judgments = [];
462	  const sessions = [];
463	  const orchestration = [];
464	  let failure;
465	  let activeQuestionId = null;
466	  try {
467	    for (const agent of PARTICIPANTS) await requireExecutable(agent, executables[agent]);
468	    await runQuestionSequence(fixture.questions, async (question) => {
469	      activeQuestionId = question.id;
470	      const answerPrompts = new Map(PARTICIPANTS.map((agent) => [agent, answerPrompt(agent, question)]));
471	      appendOrchestrationRequests(orchestration, "answer", question, answerPrompts);
472	      const answerResults = await Promise.allSettled(PARTICIPANTS.map((agent) => runParticipantSession(agent, "answer", question, answerPrompts.get(agent))));
473	      const answerFailures = [];
474	      for (let index = 0; index < answerResults.length; index += 1) {
475	        const result = answerResults[index];
476	        const agent = PARTICIPANTS[index];
477	        const settled = await retainSettledSession({ result, role: "answer", question, agent, sessions, orchestration });
478	        if (!settled) {
479	          answerFailures.push(result.reason);
480	          continue;
481	        }
482	        const answer = { questionId: question.id, agent, sessionId: settled.session.sessionId, effort: "medium", status: "completed", answer: settled.text };
483	        answers.push(answer);
484	        orchestration.push(event({ questionId: question.id, phase: "answer", agent, sessionId: answer.sessionId, timestamp: settled.session.completedAt, direction: "response", eventType: "answer_result", payload: answer }));
485	      }
486	      if (answerFailures.length > 0) throw answerFailures[0];
487	
488	      const questionAnswers = answers.filter((answer) => answer.questionId === question.id);
489	      const reviewPrompts = new Map(PARTICIPANTS.map((agent) => [agent, reviewPrompt(agent, question, questionAnswers)]));
490	      appendOrchestrationRequests(orchestration, "review", question, reviewPrompts);
491	      const reviewResults = await Promise.allSettled(PARTICIPANTS.map((agent) => runParticipantSession(agent, "review", question, reviewPrompts.get(agent))));
492	      const reviewFailures = [];
493	      for (let index = 0; index < reviewResults.length; index += 1) {
494	        const result = reviewResults[index];
495	        const reviewerAgent = PARTICIPANTS[index];
496	        const settled = await retainSettledSession({ result, role: "review", question, agent: reviewerAgent, sessions, orchestration });
497	        if (!settled) {
498	          reviewFailures.push(result.reason);
499	          continue;
500	        }
501	        try {
502	          const reviewText = reviewerAgent === forcedReviewParseFailureAgent ? "forced invalid review JSON" : settled.text;
503	          const reviewJudgments = parseJudgments(reviewText, reviewerAgent, question);
504	          settled.session.judgments = reviewJudgments;
505	          judgments.push(...reviewJudgments);
506	          orchestration.push(event({ questionId: question.id, phase: "review", agent: reviewerAgent, sessionId: settled.session.sessionId, timestamp: settled.session.completedAt, direction: "response", eventType: "review_result", payload: reviewJudgments }));
507	        }
508	        catch (error) {
509	          settled.session.status = "failed";
510	          settled.session.error = { name: error.name, message: error.message };
511	          reviewFailures.push(error);
512	          orchestration.push(event({
513	            questionId: question.id,
514	            phase: "review",
515	            agent: reviewerAgent,
516	            sessionId: settled.session.sessionId,
517	            timestamp: settled.session.completedAt,
518	            direction: "response",
519	            eventType: "review_failure",
520	            payload: { name: error.name, message: error.message, status: "failed" },
521	          }));
522	        }
523	      }
524	      if (reviewFailures.length > 0) throw reviewFailures[0];
525	      return {
526	        answers: answers.filter((answer) => answer.questionId === question.id),
527	        judgments: judgments.filter((judgment) => judgment.questionId === question.id),
528	        sessions: sessions.filter((session) => session.questionId === question.id),
529	        files: await collectFiles(artifactRoot),
530	      };
531	    });
532	
533	    await writeJsonl(join(artifactRoot, "orchestration.jsonl"), orchestration);
534	    await writeJson(join(artifactRoot, "answers.json"), answers);
535	    await writeJson(join(artifactRoot, "peer-judgments.json"), judgments);
536	    await writeJson(join(artifactRoot, "sessions.json"), sessions);
537	    await writeJson(join(artifactRoot, "summary.json"), { runId, status: "passed", counts: { questions: fixture.questions.length, answers: answers.length, sessions: sessions.length, judgments: judgments.length }, minimumAccuracy: Math.min(...judgments.map(({ accuracy }) => accuracy)) });
538	    const evidence = await buildLiveCoreEvidence({ answers, judgments, sessions, orchestration });
539	    assertFourAgentCoreEvidence(evidence);
540	  } catch (error) {
541	    failure = error;
542	    orchestration.push(event({
543	      questionId: activeQuestionId ?? "PRECHECK",
544	      phase: "run",
545	      agent: "orchestrator",
546	      sessionId: `${runId}-run`,
547	      direction: "internal",
548	      eventType: "run_failure",
549	      payload: { name: error.name, message: error.message },
550	    }));
551	    throw error;
552	  } finally {
553	    await writeJsonl(join(artifactRoot, "orchestration.jsonl"), orchestration);
554	    await writeJson(join(artifactRoot, "answers.json"), answers);
555	    await writeJson(join(artifactRoot, "peer-judgments.json"), judgments);
556	    await writeJson(join(artifactRoot, "sessions.json"), sessions);
557	    await writeJson(join(artifactRoot, "summary.json"), { runId, status: failure ? "failed" : "passed", failure: failure ? { name: failure.name, message: failure.message, stack: failure.stack } : null, counts: { questions: fixture.questions.length, answers: answers.length, sessions: sessions.length, judgments: judgments.length }, minimumAccuracy: judgments.length > 0 ? Math.min(...judgments.map(({ accuracy }) => Number.isInteger(accuracy) ? accuracy : -1)) : null });
558	  }
559	});
