function Get-ToolText($resp,$marker){
  foreach($l in [IO.File]::ReadLines((Resolve-Path $resp))){
    if(-not $l.Contains($marker) -or -not $l.Contains('tool_result')){ continue }
    $o=$l|ConvertFrom-Json -Depth 60
    foreach($tr in ($o.message.content | Where-Object { $_.type -eq 'tool_result' })){
      $txt= if($tr.content -is [string]){$tr.content}else{ ($tr.content | ForEach-Object { $_.text }) -join "`n" }
      if($txt.Contains($marker)){ return $txt }
    }
  }
  return $null
}
function Strip($txt){ ($txt -split "`r?`n") | Where-Object { $_ -match '^\s*\d+\t' } | ForEach-Object { $_ -replace '^\s*\d+\t','' } }
$cases=@(
 @{name='R9SR vs R9-time';resp='20261107T183919-four-agent-reasoning-r9\response.jsonl';marker='PLAN-FRENEMY-002 R9 pre-HV self-review';cur='20261107T183919-four-agent-reasoning-r9\pre-hv-self-review.md'},
 @{name='R8SR vs R9-time';resp='20261107T183919-four-agent-reasoning-r9\response.jsonl';marker='# R8 pre-HV self-review';cur='20261107T170539-four-agent-reasoning-r8\pre-hv-self-review.md'},
 @{name='R10SR vs R10-time';resp='20261107T193400-four-agent-reasoning-r10\response.jsonl';marker='PLAN-FRENEMY-002 R10 pre-HV self-review';cur='20261107T193400-four-agent-reasoning-r10\pre-hv-self-review.md'}
)
foreach($c in $cases){
  $t=Get-ToolText $c.resp $c.marker
  if(-not $t){ "== $($c.name): original not found"; continue }
  $orig=@(Strip $t); $curr=@(Get-Content $c.cur)
  $diff=0; for($i=0;$i -lt $orig.Count;$i++){ if($i -ge $curr.Count -or $orig[$i] -ne $curr[$i]){ $diff++; "  line $($i+1) differs:`n    ORIG: $($orig[$i])`n    CURR: $($curr[$i])" } }
  "== $($c.name): origLines=$($orig.Count) currLines=$($curr.Count) prefixDiffs=$diff"
}

