475	function Invoke-FourAgentReasoningIntegrationProject {
476	    [CmdletBinding()]
477	    param([Parameter(Mandatory)][string]$OutputDirectory)
478	
479	    $selected = @{
480	        claude = $script:SelectedClaudeExecutable
481	        codex = $script:SelectedCodexExecutable
482	        grok = $script:SelectedGrokExecutable
483	        cline = $script:SelectedClineExecutable
484	    }
485	    foreach ($entry in $selected.GetEnumerator()) { Assert-FourAgentExecutable -Name "$($entry.Key)Executable" -Path ([string]$entry.Value) }
486	    $artifactRoot = Join-Path $resultRoot 'four-agent-reasoning'
487	    $archivePath = Join-Path $resultRoot 'four-agent-reasoning-review.zip'
488	    $runStartedAt = (Get-Date).ToString('s')
489	    [IO.Directory]::CreateDirectory($OutputDirectory) | Out-Null
490	    [IO.Directory]::CreateDirectory($artifactRoot) | Out-Null
491	    $gitHead = (& git -C $repo rev-parse HEAD).Trim()
492	    if ($LASTEXITCODE -ne 0) { throw 'Unable to resolve the git head for the four-agent integration.' }
493	    $environment = @{
494	        FRENEMY_FOUR_AGENT_RUN_ID = $TestRunId
495	        FRENEMY_FOUR_AGENT_RESULT_ROOT = $artifactRoot
496	        FRENEMY_CLAUDE_EXECUTABLE = [IO.Path]::GetFullPath($selected.claude)
497	        FRENEMY_CODEX_EXECUTABLE = [IO.Path]::GetFullPath($selected.codex)
498	        FRENEMY_GROK_EXECUTABLE = [IO.Path]::GetFullPath($selected.grok)
499	        FRENEMY_CLINE_EXECUTABLE = [IO.Path]::GetFullPath($selected.cline)
500	        FRENEMY_GIT_HEAD = $gitHead
